<script lang="ts">
  import { onMount } from 'svelte';
  import { page } from '$app/stores';
  import { api } from '$lib/api/client';
  import { formatMoney, formatNumber, INSTITUTION_LABEL, VENUE_LABEL, GOVERNANCE_LABEL, VENUE_USAGE_LABEL } from '$lib/format';
  import Crest from '$lib/components/Crest.svelte';
  import ErrorNotice from '$lib/components/ErrorNotice.svelte';
  import ClubOrgChart from '$lib/components/ClubOrgChart.svelte';
  import FinanceSheet from '$lib/components/FinanceSheet.svelte';

  const clubId=$derived($page.params.id);
  const tabs=[['general','General'],['plantilla','Plantilla'],['estadio','Estadio'],['organigrama','Organigrama'],['instalaciones','Instalaciones'],['finanzas','Finanzas']] as const;
  let club=$state<any>(null),error=$state<unknown>(null),tab=$state<(typeof tabs)[number][0]>('general'),visiblePlayers=$state(18),sentinel=$state<HTMLDivElement>();
  onMount(()=>{api.get<any>(`/clubs/${clubId}`).then((data)=>club=data).catch((err)=>error=err)});
  $effect(()=>{if(!sentinel)return;const observer=new IntersectionObserver(([entry])=>{if(entry.isIntersecting)visiblePlayers+=18},{rootMargin:'200px'});observer.observe(sentinel);return()=>observer.disconnect()});
</script>

<ErrorNotice {error}/>
{#if club}
  <header class="club-head"><Crest primary={club.primary_color} secondary={club.secondary_color} shape={club.crest_shape} motif={club.crest_motif} size={54} title={club.name}/><div><div class="eyebrow">{INSTITUTION_LABEL[club.institutional_type]??club.institutional_type}</div><h1>{club.name}</h1><p>{club.home_place?.name} · Fundado en {club.foundation_year}</p></div></header>
  <nav class="tabs" aria-label="Secciones del club">{#each tabs as [value,label]}<button class:active={tab===value} onclick={()=>tab=value}>{label}</button>{/each}</nav>

  {#if tab==='general'}
    <div class="grid three"><div class="stat"><div class="value">{club.roster.length}</div><div class="label">jugadores</div></div><div class="stat"><div class="value">{formatNumber(club.fan_base)}</div><div class="label">base social</div></div><div class="stat"><div class="value">{club.titles.length}</div><div class="label">títulos</div></div></div>
    <div class="grid sidebar" style="margin-top:12px"><section class="panel"><h2>El club</h2><p class="muted">{club.history_note}</p><div class="compact-list"><div><span>Competición actual</span><strong>{club.competitions.map((item:any)=>item.name).join(' · ')||'Sin competición'}</strong></div><div><span>Gobierno</span><strong>{GOVERNANCE_LABEL[club.organization?.governance]??club.organization?.governance??'—'}</strong></div><div><span>Estadio</span><strong>{club.venue?.name??'Sin sede'}</strong></div></div></section><section class="panel"><h2>En números</h2><div class="compact-list"><div><span>Presupuesto</span><strong>{formatMoney(club.finances.annual_budget,club.finances.currency)}</strong></div><div><span>Caja disponible</span><strong>{formatMoney(club.finances.cash,club.finances.currency)}</strong></div><div><span>Deuda</span><strong>{formatMoney(club.finances.debt,club.finances.currency)}</strong></div></div></section></div>
  {:else if tab==='plantilla'}
    <div class="section-title"><div><h2>Plantilla</h2><p>{club.roster.length} jugadores registrados.</p></div></div>
    <div class="roster-grid">{#each club.roster.slice(0,visiblePlayers) as player,index (player.id)}<a class="player-card" href={`/personas/${player.id}`}><span class="number">{String(index+1).padStart(2,'0')}</span><div><strong>{player.name}</strong><span>{player.primary_position} {player.pitcher_role?`· ${player.pitcher_role}`:''}</span></div><div class="player-meta"><strong>{player.age}</strong><span>años</span></div><div class="player-meta"><strong>{player.bats}/{player.throws}</strong><span>B/L</span></div><div class="potential"><i style={`width:${Math.min(player.scouted_potential*100,100)}%`}></i><span>Proyección {(player.scouted_potential*100).toFixed(0)}</span></div></a>{/each}</div><div bind:this={sentinel} class="infinite-sentinel">{visiblePlayers<club.roster.length?'Cargando más jugadores…':'Plantilla completa'}</div>
  {:else if tab==='estadio'}
    {#if club.venue}<section class="stadium"><div><div class="eyebrow">{VENUE_LABEL[club.venue.type]??club.venue.type}</div><h1>{club.venue.name}</h1><p>{club.venue.place} · {club.venue.surface} · {club.venue.elevation_m} m de altitud</p></div><svg viewBox="0 0 200 180" role="img" aria-label="Dimensiones del terreno"><path d={`M100 165 L${100-club.venue.dimensions.left_field_m*.62} ${165-club.venue.dimensions.left_field_m*.62} Q100 ${165-club.venue.dimensions.center_field_m*1.08} ${100+club.venue.dimensions.right_field_m*.62} ${165-club.venue.dimensions.right_field_m*.62} Z`} fill="rgba(198,243,107,.12)" stroke="var(--accent-2)"/><path d="M100 165 L128 137 L100 109 L72 137 Z" fill="#4a3225"/><text x="7" y="150">{club.venue.dimensions.left_field_m}m</text><text x="87" y="28">{club.venue.dimensions.center_field_m}m</text><text x="157" y="150">{club.venue.dimensions.right_field_m}m</text></svg><div class="grid three"><div class="stat"><div class="value">{formatNumber(club.venue.capacity)}</div><div class="label">aforo</div></div><div class="stat"><div class="value">{club.venue.built_year}</div><div class="label">construcción</div></div><div class="stat"><div class="value">{club.venue.has_roof?'Sí':'No'}</div><div class="label">techo</div></div></div></section>{:else}<div class="empty-state">El club no tiene estadio registrado.</div>{/if}
  {:else if tab==='organigrama'}
    <div class="section-title"><div><h2>Organigrama</h2><p>Áreas, responsabilidades y personas que dirigen el club.</p></div></div><ClubOrgChart chart={club.chart}/>
  {:else if tab==='instalaciones'}
    <div class="section-title"><div><h2>Instalaciones</h2><p>Capacidad operativa registrada del club.</p></div></div>
    <div class="facility-grid"><section class="panel"><h2>Recinto principal</h2><div class="compact-list"><div><span>Acuerdo de uso</span><strong>{VENUE_USAGE_LABEL[club.organization?.venue_agreement]??club.organization?.venue_agreement??'—'}</strong></div><div><span>Superficie</span><strong>{club.venue?.surface??'—'}</strong></div><div><span>Mantenimiento</span><strong>{club.venue?`${(club.venue.maintenance*100).toFixed(0)}%`:'—'}</strong></div><div><span>Barda</span><strong>{club.venue?.dimensions.wall_height_m??'—'} m</strong></div></div></section><section class="panel"><h2>Capacidad institucional</h2><div class="meter"><i style={`width:${Math.min((club.resource_multiplier??0)*50,100)}%`}></i></div><p class="small muted">Multiplicador de recursos: {club.resource_multiplier?.toFixed(2)}. Este indicador resume la capacidad material disponible en la simulación.</p><div class="compact-list"><div><span>Alcance comunitario</span><strong>{club.organization?.community_reach?.toFixed(2)??'—'}</strong></div><div><span>Gestión de sede</span><strong>{club.chart?.units?.some((u:any)=>u.positions?.some((p:any)=>p.authority?.includes('manage_facilities'))) ? 'Área responsable' : 'Sin responsable asignado'}</strong></div></div></section></div>
  {:else if tab==='finanzas'}
    <FinanceSheet finances={club.finances} ledgers={club.season_ledgers}/>
  {/if}
{:else if !error}<div class="empty-state">Cargando club…</div>{/if}

<style>
  .club-head{display:flex;align-items:center;gap:14px;padding:12px 0;margin:0}.club-head h1{margin:2px 0}.club-head p{margin:0;color:var(--muted);font-size:12px}.roster-grid{display:grid;gap:7px}.player-card{display:grid;grid-template-columns:35px minmax(180px,1fr) 55px 55px 150px;align-items:center;gap:10px;padding:9px 12px;color:var(--text);text-decoration:none;background:var(--panel);border:1px solid var(--line);border-radius:9px}.player-card:hover{border-color:var(--accent)}.number{font:700 15px var(--mono);color:var(--accent)}.player-card>div>strong,.player-card>div>span,.player-meta strong,.player-meta span{display:block}.player-card>div>span,.player-meta span{font-size:9px;color:var(--muted);text-transform:uppercase}.potential{position:relative;height:5px;background:var(--panel-3);border-radius:9px}.potential i,.meter i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),var(--accent-2));border-radius:inherit}.potential span{position:absolute;right:0;top:8px;font-size:8px!important}.stadium{display:grid;grid-template-columns:1fr 300px;gap:20px;align-items:center;padding:22px;background:linear-gradient(145deg,var(--panel-2),var(--panel));border:1px solid var(--line);border-radius:12px}.stadium svg{width:100%;height:230px}.stadium text{fill:var(--muted);font-size:8px}.stadium .grid{grid-column:1/-1}.compact-list{display:grid}.compact-list>div{display:flex;justify-content:space-between;gap:18px;padding:9px 0;border-bottom:1px solid var(--line);font-size:12px}.compact-list span{color:var(--muted)}.facility-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.meter{height:8px;background:var(--panel-3);border-radius:10px;margin:18px 0}@media(max-width:700px){.player-card{grid-template-columns:30px 1fr 45px}.player-meta:nth-of-type(2),.potential{display:none}.stadium,.facility-grid{grid-template-columns:1fr}.stadium svg{height:180px}}
</style>
